for i, d in enumerate(demos):
    inp = np.array(d['input'])
    out = np.array(d['output'])
    h, w = inp.shape

    bg = inp[0,0]
    row_2s = col_2s = row_8s = col_8s_idx = None
    for r in range(h):
        if np.all(inp[r] == 2): row_2s = r
    for c in range(w):
        if np.all(inp[:, c] == 2): col_2s = c
    for r in range(h):
        if np.all(out[r] == 8): row_8s = r
