        if np.all(out[:, c] == 8):
            col_8s_idx = c
            break

    # Empty region calculation
    if row_2s is not None:
        # Find contiguous empty region containing the 8s
        empty_rows = []
        for r in range(h):
            if np.all(inp[r] == bg):
                empty_rows.append(r)
        empty_blocks = []
        if empty_rows:
            start, end = empty_rows[0], empty_rows[0]
            for r in empty_rows[1:]:
                if r == end + 1:
                    end = r
                else:
                    empty_blocks.append((start, end))
