            print(f"    rows {blk[0]}-{blk[1]} (size {blk[1]-blk[0]+1})")
        print()

    if col_2s is not None:
        empty_cols = []
        for c in range(w):
            if np.all(inp[:, c] == bg):
                empty_cols.append(c)
        empty_blocks = []
        if empty_cols:
            start, end = empty_cols[0], empty_cols[0]
            for c in empty_cols[1:]:
                if c == end + 1:
                    end = c
                else:
                    empty_blocks.append((start, end))
                    start, end = c, c
            empty_blocks.append((start, end))
        print(f"Demo {i+1}: col_2s={col_2s}, 8s@col{col_8s_idx}")
        print(f"  Empty col blocks: {len(empty_blocks)}")
        for blk in empty_blocks:
            print(f"    cols {blk[0]}-{blk[1]} (size {blk[1]-blk[0]+1})")
        print()

